import sys; sys.path.insert(0,"/workspace/social/posts"); from build10 import build
B=r'''<style>.box p,.box li{font-size:19.5px;line-height:1.28}.box h2{font-size:25px;margin-bottom:5px}.tbl{font-size:17.5px}.tbl th,.tbl td{padding:3px 6px}.iq ol{font-size:18.5px;line-height:1.28}.pill{font-size:15px}.grid{gap:10px}.handle{bottom:-12px}.box{padding:9px 12px}.tagline{font-size:19px;margin-bottom:6px}</style>
<div class="title">🔁 HxGN EAM Core Repair <span class="badge">CHEAT SHEET</span></div>
<div class="tagline">Repairable / rotable spares: return the broken core, repair it in-house or at a supplier, receive it back to stock. (Infor EAM 11.7 Core Repair brief)</div>
<div class="grid">
<div class="box c1"><h2>1. What is a core?</h2><ul><li>A stocked part, used on equipment, that gets <b>repaired</b> when broken</li><li>a.k.a. repairable or rotable spare</li><li>Works for parts <b>tracked by asset</b> (qty always 1) and not tracked by asset</li><li>Setup: tick <b>Track Cores</b> on the Parts screen (also needed for Track by Asset parts)</li></ul></div>
<div class="box c2"><h2>2. Identify the core</h2><ul><li>Issue the new part → warning that a core return may follow (<b>RRISSWAR</b>)</li><li>Issue/Return Parts or WO Parts tab: Return + <b>Core Return</b> ✔</li><li>Child Equipment Replacement screen: core return / return / scrap</li><li>Unreturned Cores screen: issued qty &gt; returned qty</li></ul></div>
<div class="box c3"><h2>3. Store quantities</h2><table class="tbl"><tr><th>Step</th><th>Moves qty</th></tr><tr><td>Core Return</td><td>→ Qty to repair (not on hand)</td></tr><tr><td>Repair issue (internal)</td><td>to repair → at shop</td></tr><tr><td>PO approval (external)</td><td>to repair → at supplier</td></tr><tr><td>Approved receipt</td><td>shop / supplier → on hand</td></tr></table></div>
<div class="box c4"><h2>4. Equipment Replacement tab</h2><ul><li>On the Work Orders screen; child must sit under the WO equipment</li><li>Allows <b>substitute parts</b> + condition filter</li><li>New asset inherits <b>all parents</b>, dependency, System/Assembly/Component Level + Component Location</li></ul></div>
<div class="box c5"><h2>5. Internal repair</h2><ul><li>WO Type <b>Repairable Spare</b> → Repair Parts tab</li><li>Part + Store + Qty to Repair → <b>Assign Repair Details</b></li><li>Assets go To be repaired → <b>In repair</b></li><li>Generate WOs: <i>Generate WOs for Repairable Cores</i></li><li>Receive on <b>Internal Repair Receipts</b> (Qty Received / Scrapped, bin) and approve</li></ul></div>
<div class="box c6"><h2>6. External repair</h2><ul><li>Requisition line Type <b>External Repair</b></li><li>Assign Repair Details only after the line is approved</li><li>Generate Requisitions: <i>Generate External Repair Requisitions</i> (grouped by Preferred Supplier)</li><li>PO approval → Repair issue; receive on <b>PO Receipts</b></li></ul></div>
<div class="box c7"><h2>7. Parts › Repair Details tab</h2><ul><li>Per store (Stores tab record first)</li><li>Internal or External (drives auto-generation only)</li><li>Default Core Bin · Auto-Assign · Use Stock Method</li><li>Internal: WO Equipment, Department, Standard WO, Internal Repair Price</li><li>External: Preferred Supplier, Min Repair Qty, Lead Time</li></ul></div>
<div class="box c8"><h2>8. Install parameters</h2><table class="tbl"><tr><td><b>RRISSWAR</b></td><td>core-return warning on issue</td></tr><tr><td><b>RSPCOMP</b></td><td>show Qty Completed, limit receipts</td></tr><tr><td><b>RPPRCCAL</b></td><td>manual repair price YES/NO</td></tr><tr><td><b>CHILDTXN</b></td><td>CHEQ txn for dependent children</td></tr></table></div>
<div class="bottom">
<div class="box" style="border-color:#1a5f7a"><h2 style="color:#1a5f7a">9a. Core flow</h2><div class="flow" style="flex-wrap:wrap;row-gap:4px"><span class="pill">Issue new</span><span class="arr">→</span><span class="pill">Core Return</span><span class="arr">→</span><span class="pill">Qty to repair</span><span class="arr">→</span><span class="pill">WO / REQ→PO</span><span class="arr">→</span><span class="pill">Receipt</span><span class="arr">→</span><span class="pill">On hand</span></div></div>
<div class="box iq"><h2>9b. Consultant tips</h2><ol><li>One WO Equipment per part = repair cost history</li><li>Fill Store on Repair Parts or auto-assign won't work</li><li>Review Unreturned Cores regularly</li><li>Compare repair cost vs buying new</li></ol></div>
<div class="box" style="border-color:#2d8a5a"><h2 style="color:#2d8a5a">9c. Key points</h2><ul><li>Track Cores ✔</li><li>Core Return ≠ Return</li><li>Approve receipts</li></ul></div>
</div></div>'''
build("/workspace/social/posts/2026-10-20-linkedin-eam-core-repair",B,1350,"Rahul Kumar")
